from h34 import *
M=mcq;F=tf;S=short;N=num
b='<rect width="720" height="300" fill="#f3f9ee"/><circle cx="360" cy="150" r="52" fill="#fde8a8" stroke="#c98b1c" stroke-width="3"/><text x="360" y="146" text-anchor="middle" font-size="16" font-weight="bold">Our</text><text x="360" y="168" text-anchor="middle" font-size="16" font-weight="bold">Community</text>'
items=[(110,50,"Shopkeeper","sells goods"),(360,28,"Road","connects places"),(610,50,"Health centre","treats illness"),(90,250,"Police","gives safety"),(360,278,"School","teaches us"),(630,250,"Park","play and meet")]
for x,y,n,w in items:
    b+=f'<line x1="360" y1="150" x2="{x}" y2="{y}" stroke="#7a9a5a" stroke-width="2"/><rect x="{x-62}" y="{y-20}" width="124" height="40" rx="10" fill="#fff" stroke="#7a9a5a" stroke-width="2"/><text x="{x}" y="{y-3}" text-anchor="middle" font-size="14" font-weight="bold">{n}</text><text x="{x}" y="{y+13}" text-anchor="middle" font-size="12">{w}</text>'
svgfile('c4evs-living-community.svg',720,300,b)
chapter(4,'evs','living-together','Living Together',
 ('A tour around my village','Chandan lives in a village with a big playground and a banyan tree where the elders sit and talk. One day his school friends plan to clean the park and plant trees for Van Mahotsav, and the whole village joins in. By the end of the day a muddy, broken park has become a happy place for everyone. This chapter shows how people and places are connected, and how a community can do big things when everyone helps.'),
 [('People and places are connected',['Chandan invites us to look at his village: a playground, a banyan tree, shops, roads and a health centre.','Every place in a community has a purpose and every person has a job that helps others.','A shopkeeper sells food, clothes and things we need every day, and also sells local products.','A road connects people who live in different areas and lets goods and services move easily.','A health centre treats us when we are ill, the police keep us safe and a school helps us learn.','So people and places depend on each other, and that togetherness is what we call a community.']),
  ('Why shared places matter',['Parks, schools, hospitals and bus stops are public places that everyone can use.','Public places are used for playing, relaxing and meeting others, and people also come together to clean and decorate them.','Think what would happen if a school or a hospital was missing from your locality. Life would be much harder.','It is our duty to keep these shared places clean and safe, for example by not throwing litter and by reporting damage to elders.','These shared experiences bring us closer and create happy memories.']),
  ('Van Mahotsav, the tree planting festival',['Van Mahotsav is also called the Tree Planting Festival and is celebrated every year in India during the rainy season, from 1 July to 7 July.','People plant trees on these days to protect the environment and make the earth greener.','John suggested cleaning the park near the school and planting trees around it.','Mallika said her grandmother walks there every morning, so clean paths and trees would give her better air to breathe.','Chandan said they should invite their families too, and the children made a colourful poster to invite everyone.']),
  ('Helping hands',['The parents decided to help as well, and every villager brought something different to offer.','Sameer had wood and nails and offered to fix the benches, and Babita offered to repair the street light.','Noor brought saplings from her plant nursery to plant along the boundary of the park.','Many kinds of work were needed: a mason mends walls using bricks and cement with a trowel, a carpenter fixes benches, an electrician repairs lights and a gardener plants and waters.','Babita said that if everyone works together, the park will be ready in no time, and she was right.','You can interview family and neighbours about their work by asking what they like most, what tools they use and what challenges they face.']),
  ('Working together in times of need',['In Kanker, Chhattisgarh, the Chinar river often overflows in the rainy season, and it was hard to reach schools and hospitals.','In 2024 the whole community came together and built a simple but strong bridge in just two days using bamboo, stones and other material.','Now students can reach their schools and villagers can cross the river easily.','This shows why it is important for communities to come together when there is a need.','Animals do this too. An ant colony is like a big community where some ants collect food, some look after the babies and some guard the home, and bees also share jobs like gathering food and building hives.']),
  ('Sharing a meal and sharing festivals',['After the tree plantation, a community feast was held and the villagers brought vegetables and cereals.','Children handed out banana leaves and volunteers served food, and everybody sat together to eat, chat and laugh.','After the feast the leaves were put in a pit, and leaves buried in a pit become manure that makes the soil better.','In Assam, on Uruka, the first day of Magh Bihu on 14 January, people build a bamboo and hay hut called a Bhela Ghar and end with a big feast, cooking, eating and dancing together.','In Sikkim, at harvest time, people from the community help each other with the crops, and the helpers who know farming well are called Khetala.']),
  ('Our school, our team',['A school is a community too. Teachers help us learn, the bus driver brings us safely and caretakers keep the school clean.','Everyone has a role, and when each person does their part the school runs well.','You can form groups of four or five to do a tree plantation, a cleanliness drive or make things from leaves, like a leaf plate or a garland.','Afterwards think about what material you used and what you learnt, and ask how working together made the activity more useful.'])],
 [('Chandan\'s friends want to make the park better. Who can help, and how?',[('List the work: repair benches, mend walls, fix the street light, bring saplings, clean the paths, cook food.','Each job needs different skills.'),('Match people to jobs: a carpenter or a neighbour with wood fixes benches, a mason mends walls, an electrician repairs lights, Noor brings plants.','People use what they have and what they know.'),('Children can clean, water the plants and make posters.','Everyone, young or old, can help in some way.'),('Together the park is ready quickly.','Shared work finishes faster and is more fun.')]),
  ('Why did the villagers build a bamboo bridge, and what did it change?',[('The river overflowed in the rainy season.','Goods and vehicles could not move and people could not reach school or hospital.'),('The whole community built a bridge in two days from bamboo and stones.','Many hands made the work quick.'),('Now children reach school and villagers cross easily.','The bridge solved a problem that no single person could solve alone.')])],
 ('Explain, in your own words, how people in a community help each other. Use an example from this chapter.',['People and places are connected and depend on each other','In the park example everyone gave something: skills, tools, plants, time','Working together solves bigger problems like the bamboo bridge','Festivals and meals are shared'],['One person can do everything alone','Only adults can help the community','Public places belong to nobody so we need not look after them']),
 ['A community is people and places connected by living together and helping each other.','Public places like parks, schools and roads should be kept clean and safe by everyone.','Van Mahotsav is the tree planting festival, 1 to 7 July, in the rainy season.','Different people give different skills, tools and time, and the work gets done together.','Communities in different places share festivals and meals, like Uruka in Assam and the Khetala in Sikkim.'],
 [M('1',1,'When is Van Mahotsav celebrated?','From 1 July to 7 July, in the rainy season',[('From 1 January to 7 January','That is winter, not the rainy season'),('In March, in spring','It is celebrated in the rainy season')],'Van Mahotsav is celebrated every year from 1 to 7 July.'),
  M('2',1,'What do people do during Van Mahotsav?','Plant trees',[('Burn crackers','That is not part of this festival'),('Cut down old trees','The festival protects trees, not cuts them')],'They plant trees to make the earth greener.'),
  M('3',1,'What did Noor bring for the park?','Saplings from her plant nursery',[('Bricks and cement','The mason uses those'),('Wood and nails','Sameer brought wood and nails')],'Noor brought saplings to plant along the boundary.'),
  M('4',1,'Who offered to repair the street light?','Babita',[('Sameer','Sameer offered to fix the benches'),('John','John suggested cleaning the park')],'Babita said she would repair the street light.'),
  M('5',2,'Which tool does a mason use for mending walls?','A trowel',[('A hammer for nails only','The chapter gives the trowel as the mason tool'),('A broom','A broom is for sweeping')],'The mason mends walls using bricks and cement with a trowel.'),
  M('6',2,'Why did the Kanker villagers build a bridge?','The Chinar river overflowed in the rainy season and blocked their way',[('They wanted to see the river from above','The bridge solved a real problem'),('A shop was far away','It was about schools and hospitals')],'The overflowing river made it hard to reach school and hospital.'),
  M('7',2,'How long did the Kanker villagers take to build the bridge?','Two days',[('Two months','It was done in just two days'),('Two years','It was done in just two days')],'Working together they built it in two days.'),
  M('8',2,'In Assam, what is the Bhela Ghar?','A hut built of bamboo and hay on Uruka',[('A boat for the festival','It is a hut'),('A kind of sweet','It is a hut')],'On Uruka people build a Bhela Ghar and end with a feast.'),
  M('9',2,'What are the specialist farming helpers in Sikkim called?','Khetala',[('Bhela','Bhela is the Assam hut'),('Mason','A mason mends walls')],'Khetala are the agriculture specialists who help at harvest.'),
  M('10',2,'What happens to leaves buried in a pit?','They become manure',[('They turn into plastic','Leaves rot into manure'),('They never change','They rot and enrich the soil')],'Buried leaves become manure and improve the soil.'),
  F('11',2,'A community works well when everybody does their part.',True,'Each person gives skills, tools or time.'),
  F('12',3,'Ants have no jobs and do everything alone.',False,'An ant colony shares jobs: collecting food, caring for babies and guarding the home.')],
 svgs=[('c4evs-living-community','A circle named Our Community is joined to a shopkeeper, road, health centre, police, school and park.','Every person and place in a community helps in some way.')],
 keep=['community','Van Mahotsav'])
